import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"FAQ — Installation, recognition and speech synthesis","description":"Mutelink FAQ: installation, updates, recognition, voices, translation, VR controls and free versus paid features.","frontmatter":{"title":"FAQ — Installation, recognition and speech synthesis","description":"Mutelink FAQ: installation, updates, recognition, voices, translation, VR controls and free versus paid features.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/help/faq"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"FAQ — Installation, recognition and speech synthesis | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink FAQ: installation, updates, recognition, voices, translation, VR controls and free versus paid features."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/help/faq"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"FAQ — Installation, recognition and speech synthesis | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink FAQ: installation, updates, recognition, voices, translation, VR controls and free versus paid features."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/faq"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/faq"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}]]},"headers":[],"relativePath":"en/help/faq.md","filePath":"en/help/faq.md"}'),i={name:"en/help/faq.md"};function r(s,e,l,h,u,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A {#q-a}&quot;">​</a></h1><p>Common questions. For problems, see <a href="/Mutelink-releases/en/help/troubleshooting">Troubleshooting</a>.</p><h2 id="インストール・更新" tabindex="-1">Installation and updates <a class="header-anchor" href="#インストール・更新" aria-label="Permalink to &quot;Installation and updates {#インストール・更新}&quot;">​</a></h2><h3 id="「windowsによってpcが保護されました」と出ます" tabindex="-1">Windows says it protected my PC <a class="header-anchor" href="#「windowsによってpcが保護されました」と出ます" aria-label="Permalink to &quot;Windows says it protected my PC {#「windowsによってpcが保護されました」と出ます}&quot;">​</a></h3><p>This can appear because the app is not code-signed. Click More info, then Run anyway. No administrator privileges are needed.</p><h3 id="新しいバージョンが出たことは、どうやって分かりますか" tabindex="-1">How do I know about new versions? <a class="header-anchor" href="#新しいバージョンが出たことは、どうやって分かりますか" aria-label="Permalink to &quot;How do I know about new versions? {#新しいバージョンが出たことは、どうやって分かりますか}&quot;">​</a></h3><p>The app notifies you at startup. You can also check in Settings &gt; Other &gt; About.</p><h3 id="設定の説明は、どこにありますか" tabindex="-1">Where are setting explanations? <a class="header-anchor" href="#設定の説明は、どこにありますか" aria-label="Permalink to &quot;Where are setting explanations? {#設定の説明は、どこにありますか}&quot;">​</a></h3><p>Press “?” at the top right of settings to show explanations beside each option. This site does not list every setting.</p><h3 id="設定の項目が、少なく見えます" tabindex="-1">Why are so few settings visible? <a class="header-anchor" href="#設定の項目が、少なく見えます" aria-label="Permalink to &quot;Why are so few settings visible? {#設定の項目が、少なく見えます}&quot;">​</a></h3><p>Settings &gt; Usage shows only options relevant to your chosen uses. Choose Show all on the same page to see everything.</p><h2 id="音声認識" tabindex="-1">Speech recognition <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;Speech recognition {#音声認識}&quot;">​</a></h2><h3 id="音声認識のエンジンは、どれを選べばいいですか" tabindex="-1">Which recognition engine should I choose? <a class="header-anchor" href="#音声認識のエンジンは、どれを選べばいいですか" aria-label="Permalink to &quot;Which recognition engine should I choose? {#音声認識のエンジンは、どれを選べばいいですか}&quot;">​</a></h3><p>For Japanese, try Parakeet Japanese TDT or Haas-ja; English, Parakeet English; others, Qwen3-ASR or Whisper turbo. See <a href="/Mutelink-releases/en/compare/speech-recognition">engine comparisons</a>.</p><h3 id="声を、pcの外に出したくありません" tabindex="-1">I want my audio to stay on my PC <a class="header-anchor" href="#声を、pcの外に出したくありません" aria-label="Permalink to &quot;I want my audio to stay on my PC {#声を、pcの外に出したくありません}&quot;">​</a></h3><p>Local Parakeet, Haas-ja, Qwen3-ASR and Whisper turbo keep audio on your PC. Cloud Web Speech/Google send it to Microsoft/Google (<a href="/Mutelink-releases/en/about/privacy">Privacy</a>).</p><h3 id="友達の名前が、正しく認識されません" tabindex="-1">Friends’ names are recognized incorrectly <a class="header-anchor" href="#友達の名前が、正しく認識されません" aria-label="Permalink to &quot;Friends’ names are recognized incorrectly {#友達の名前が、正しく認識されません}&quot;">​</a></h3><p>For Parakeet Japanese TDT, registering words under Settings &gt; Speaking &gt; Language and recognition &gt; Words and names makes them more likely to appear.</p><h3 id="言語の「自動」が選べません" tabindex="-1">I cannot select Auto language <a class="header-anchor" href="#言語の「自動」が選べません" aria-label="Permalink to &quot;I cannot select Auto language {#言語の「自動」が選べません}&quot;">​</a></h3><p>Auto is available only for Qwen3-ASR and Whisper turbo.</p><h2 id="読み上げの声" tabindex="-1">Voices <a class="header-anchor" href="#読み上げの声" aria-label="Permalink to &quot;Voices {#読み上げの声}&quot;">​</a></h2><h3 id="どの声を選べばいいですか" tabindex="-1">Which voice should I choose? <a class="header-anchor" href="#どの声を選べばいいですか" aria-label="Permalink to &quot;Which voice should I choose? {#どの声を選べばいいですか}&quot;">​</a></h3><p>Choose VOICEVOX for character voices or no GPU, Irodori-TTS for fast natural Japanese, and Qwen3-TTS for other languages. Listen to <a href="/Mutelink-releases/en/compare/voices">voice samples</a>.</p><h3 id="gpuは必要ですか" tabindex="-1">Do I need a GPU? <a class="header-anchor" href="#gpuは必要ですか" aria-label="Permalink to &quot;Do I need a GPU? {#gpuは必要ですか}&quot;">​</a></h3><p>VOICEVOX and chatbox-only use do not need a GPU. Irodori-TTS and Qwen3-TTS need a Vulkan-compatible GPU.</p><h3 id="自分の声に似せた声で、読み上げられますか" tabindex="-1">Can it speak in a voice like mine? <a class="header-anchor" href="#自分の声に似せた声で、読み上げられますか" aria-label="Permalink to &quot;Can it speak in a voice like mine? {#自分の声に似せた声で、読み上げられますか}&quot;">​</a></h3><p>Register a recording with Irodori-TTS or Qwen3-TTS (<a href="/Mutelink-releases/en/about/supporter">supporter feature</a>). Use only your own voice or one whose owner has explicitly consented.</p><h3 id="日本語以外も、読み上げられますか" tabindex="-1">Can it read languages other than Japanese? <a class="header-anchor" href="#日本語以外も、読み上げられますか" aria-label="Permalink to &quot;Can it read languages other than Japanese? {#日本語以外も、読み上げられますか}&quot;">​</a></h3><p>Qwen3-TTS reads English, Chinese, Korean, German, Spanish, French, Italian, Portuguese and Russian.</p><h2 id="翻訳" tabindex="-1">Translation <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;Translation {#翻訳}&quot;">​</a></h2><h3 id="翻訳は無料ですか" tabindex="-1">Is translation free? <a class="header-anchor" href="#翻訳は無料ですか" aria-label="Permalink to &quot;Is translation free? {#翻訳は無料ですか}&quot;">​</a></h3><p>Translation, translated chatbox messages and incoming-speech translation are free. Only reading translated text aloud requires the <a href="/Mutelink-releases/en/about/supporter">supporter edition</a>.</p><h3 id="どの翻訳エンジンがいいですか" tabindex="-1">Which translation engine is best? <a class="header-anchor" href="#どの翻訳エンジンがいいですか" aria-label="Permalink to &quot;Which translation engine is best? {#どの翻訳エンジンがいいですか}&quot;">​</a></h3><p>It depends on the language. Read your language’s outputs in <a href="/Mutelink-releases/en/compare/translation">translation comparisons</a>. Choose PLaMo or TranslateGemma to keep text on your PC.</p><h3 id="訳した文を、確認してから送れますか" tabindex="-1">Can I review a translation before sending? <a class="header-anchor" href="#訳した文を、確認してから送れますか" aria-label="Permalink to &quot;Can I review a translation before sending? {#訳した文を、確認してから送れますか}&quot;">​</a></h3><p>No. Translation happens just before sending and is sent immediately.</p><h2 id="聞こえた声" tabindex="-1">Incoming speech <a class="header-anchor" href="#聞こえた声" aria-label="Permalink to &quot;Incoming speech {#聞こえた声}&quot;">​</a></h2><h3 id="聞こえた声とは何ですか" tabindex="-1">What is incoming speech? <a class="header-anchor" href="#聞こえた声とは何ですか" aria-label="Permalink to &quot;What is incoming speech? {#聞こえた声とは何ですか}&quot;">​</a></h3><p>Mutelink transcribes VRChat audio to display other people’s words. Translations can also be displayed.</p><h3 id="聞こえた声は、相手に見えますか" tabindex="-1">Can others see incoming-speech text? <a class="header-anchor" href="#聞こえた声は、相手に見えますか" aria-label="Permalink to &quot;Can others see incoming-speech text? {#聞こえた声は、相手に見えますか}&quot;">​</a></h3><p>The main-window list and VR panels are private to you. If you enable chatbox output (off by default), everyone in the instance can see it.</p><h2 id="vr" tabindex="-1">VR <a class="header-anchor" href="#vr" aria-label="Permalink to &quot;VR {#vr}&quot;">​</a></h2><h3 id="steamvrは必須ですか" tabindex="-1">Is SteamVR required? <a class="header-anchor" href="#steamvrは必須ですか" aria-label="Permalink to &quot;Is SteamVR required? {#steamvrは必須ですか}&quot;">​</a></h3><p>No. Use it on desktop without SteamVR, including keyboard shortcuts for sending and language switching (Settings &gt; Other &gt; Hotkeys).</p><h3 id="steamvrと一緒に、起動できますか" tabindex="-1">Can it start with SteamVR? <a class="header-anchor" href="#steamvrと一緒に、起動できますか" aria-label="Permalink to &quot;Can it start with SteamVR? {#steamvrと一緒に、起動できますか}&quot;">​</a></h3><p>Yes. Enable Start/exit with SteamVR under Settings &gt; Appearance &gt; VR. Registration happens when connected, so start SteamVR before Mutelink the first time.</p><h2 id="支援版・データ" tabindex="-1">Supporter edition and data <a class="header-anchor" href="#支援版・データ" aria-label="Permalink to &quot;Supporter edition and data {#支援版・データ}&quot;">​</a></h2><h3 id="支援版を買わないと、使えませんか" tabindex="-1">Must I buy the supporter edition? <a class="header-anchor" href="#支援版を買わないと、使えませんか" aria-label="Permalink to &quot;Must I buy the supporter edition? {#支援版を買わないと、使えませんか}&quot;">​</a></h3><p>No. The app is free without a purchase. See <a href="/Mutelink-releases/en/about/supporter">supporter features</a> for the differences.</p><h3 id="どんなデータが、外に送られますか" tabindex="-1">What data leaves my PC? <a class="header-anchor" href="#どんなデータが、外に送られますか" aria-label="Permalink to &quot;What data leaves my PC? {#どんなデータが、外に送られますか}&quot;">​</a></h3><p>See <a href="/Mutelink-releases/en/about/privacy">Privacy</a>.</p>',51)])])}const g=a(i,[["render",r]]);export{c as __pageData,g as default};
